import json
from typing import Any, Dict

class ConfigError(Exception):
    pass

def read_config(file_path: str) -> Dict[str, Any]:
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            config = json.load(file)
        return config
    except FileNotFoundError:
        raise ConfigError(f"Файл конфигурации {file_path} не найден.")
    except json.JSONDecodeError:
        raise ConfigError(f"Ошибка при чтении файла конфигурации {file_path}. Неверный формат JSON.")
    except Exception as e:
        raise ConfigError(f"Ошибка при чтении файла конфигурации {file_path}: {str(e)}")
